      });
      if (hasLateInjectedEvents) continue;
      let parsed: unknown;
      try {
        parsed = extractJsonObject(responseText);
      } catch (error) {
        retryMessages.push({
          role: "system",
          content: [
            `Your previous response was not valid JSON on attempt ${attempt}/${MAX_EVENT_DISPATCH_ATTEMPTS}.`,
            `Error: ${String(error)}`,
            "Return only a corrected JSON event object.",
          ].join("\n"),
        });
        continue;
      }
