  async function getChannelParticipationValidationError(
    agentName: string,
    channelId?: string,
  ): Promise<string | null> {
    const targetChannelId = channelId?.trim();
    if (!targetChannelId) return null;
    const channel = await getChannelRecord(targetChannelId);
    if (!channel) {
